/**
 * @name SQL injection in Snowflake connector
 * @description User-controlled input flowing into SQL execution could lead to SQL injection
 * @kind path-problem
 * @problem.severity error
 * @id py/sql-injection-snowflake
 * @tags security
 *        external/cwe/cwe-089
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.dataflow.new.RemoteFlowSources
import semmle.python.Concepts
import semmle.python.ApiGraphs

module SqlInjectionConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof RemoteFlowSource
  }

  predicate isSink(DataFlow::Node sink) {
    // Find SQL execution calls in Snowflake connector
    exists(DataFlow::CallCfgNode call |
      // Snowflake connector methods that execute SQL
      call = API::moduleImport("snowflake").getMember("connector").getMember("cursor").getMember("execute").getACall() or
      call = API::moduleImport("snowflake").getMember("connector").getMember("cursor").getMember("executemany").getACall() or
      call = API::moduleImport("snowflake").getMember("connector").getMember("cursor").getMember("executemany").getACall() or
      // Also check for direct calls to snowflake.connector.connect().cursor().execute()
      call = API::moduleImport("snowflake").getMember("connector").getMember("connect").getACall().getReturn().getMember("cursor").getACall().getReturn().getMember("execute").getACall() or
      call = API::moduleImport("snowflake").getMember("connector").getMember("connect").getACall().getReturn().getMember("cursor").getACall().getReturn().getMember("executemany").getACall()
    |
      // The first argument to execute() is the SQL query
      sink = call.getArg(0)
    )
  }
}

module SqlInjectionFlow = TaintTracking::Global<SqlInjectionConfig>;
import SqlInjectionFlow::PathGraph

from SqlInjectionFlow::PathNode source, SqlInjectionFlow::PathNode sink
where SqlInjectionFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "SQL injection from $@.", source.getNode(), "user input"

/**
 * @name Command injection in Snowflake connector
 * @description User-controlled input flowing into command execution could lead to arbitrary command execution
 * @kind path-problem
 * @problem.severity error
 * @id py/command-injection-snowflake
 * @tags security
 *        external/cwe/cwe-078
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.dataflow.new.RemoteFlowSources
import semmle.python.Concepts
import semmle.python.ApiGraphs

module CommandInjectionConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof RemoteFlowSource
  }

  predicate isSink(DataFlow::Node sink) {
    // Find command execution calls
    exists(DataFlow::CallCfgNode call |
      // subprocess module calls
      call = API::moduleImport("subprocess").getMember(["call", "check_call", "check_output", "run", "Popen"]).getACall() or
      call = API::moduleImport("os").getMember(["system", "popen", "popen2", "popen3", "popen4"]).getACall() or
      call = API::moduleImport("os").getMember("exec").getACall() or
      call = API::moduleImport("os").getMember("spawn").getACall() or
      // platform module calls
      call = API::moduleImport("platform").getMember("system").getACall()
    |
      // The command argument is typically the first argument
      sink = call.getArg(0)
    )
  }
}

module CommandInjectionFlow = TaintTracking::Global<CommandInjectionConfig>;
import CommandInjectionFlow::PathGraph

from CommandInjectionFlow::PathNode source, CommandInjectionFlow::PathNode sink
where CommandInjectionFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Command injection from $@.", source.getNode(), "user input"

/**
 * @name Code injection via exec in setup.py
 * @description User input flowing to exec() calls in setup.py could lead to arbitrary code execution
 * @kind path-problem
 * @problem.severity error
 * @id py/exec-injection
 * @tags security
 *        external/cwe/cwe-094
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.dataflow.new.RemoteFlowSources
import semmle.python.Concepts
import semmle.python.ApiGraphs

module ExecInjectionConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof RemoteFlowSource
  }

  predicate isSink(DataFlow::Node sink) {
    // Find exec() calls
    exists(DataFlow::CallCfgNode call |
      call = API::builtin("exec").getACall() and
      sink = call.getArg(0)  // The code argument to exec()
    )
  }
}

module ExecInjectionFlow = TaintTracking::Global<ExecInjectionConfig>;
import ExecInjectionFlow::PathGraph

from ExecInjectionFlow::PathNode source, ExecInjectionFlow::PathNode sink
where ExecInjectionFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Code injection via exec() from $@.", source.getNode(), "user input"

/**
